sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {
    // Set skip to true if part_id not mapped to anything

    // The part ids from the part id/Model map, filtered to only
	// part ids mapped to some value
    var part_ids = new BaseDataSourceReader(gs.getCurrentScopeName(), "Models")
        .getData()
        .filter(e => e.key && e.value)
		.map(e => e.key);

    var gr_is_row = new GlideRecord(source.getTableName());
    gr_is_row.addQuery("sys_import_set", import_set.sys_id);
    gr_is_row.addQuery("u_skip", false);
    gr_is_row.query();
    while (gr_is_row.hasNext()) {
        gr_is_row.next();

		// We aleady skipped rows where this field is empty
        var part_id = gr_is_row.getValue("u_part_id");

        if (part_ids.indexOf(part_id) == -1) {
            gr_is_row.setValue("u_skip", true);
            gr_is_row.setValue("u_skip_reason", "Part id not mapped");
            gr_is_row.update();
        }

    }

})(source, map, log, target);
